class Solution {
public:
    vector<int> restoreArray(vector<vector<int>>& adjacentPairs) {
        unordered_map<int, vector<int>> adj;
        adj.reserve(adjacentPairs.size() * 2);
        for (auto& p : adjacentPairs) {
            adj[p[0]].push_back(p[1]);
            adj[p[1]].push_back(p[0]);
        }
        int start = 0;
        for (auto& [k, v] : adj) {
            if (v.size() == 1) { start = k; break; }
        }
        vector<int> res;
        res.reserve(adj.size());
        int prev = INT_MIN, cur = start;
        while (true) {
            res.push_back(cur);
            bool found = false;
            for (int nxt : adj[cur]) {
                if (nxt != prev) {
                    prev = cur;
                    cur = nxt;
                    found = true;
                    break;
                }
            }
            if (!found) break;
        }
        return res;
    }
};
